"use client";

import React, { useRef } from "react";
import { motion, useScroll, useTransform, useSpring } from "framer-motion";

const ABILITIES = [
  {
    id: "density-shift",
    name: "GRAVITY CONTROL",
    description: "Manipulates gravitational force around the user. Control the pull.",
  },
  {
    id: "kinetic-anchor",
    name: "KINETIC ANCHOR",
    description: "Locks physical position against external force. Stand unmovable.",
  },
  {
    id: "vector-shift",
    name: "VECTOR SHIFT",
    description: "Redirects momentum and incoming impact away from the user. Change the direction.",
  },
  {
    id: "debt-field",
    name: "DEBT FIELD",
    description: "Stores and releases accumulated gravitational energy. All force returns.",
  },
  {
    id: "mass-shift",
    name: "MASS SHIFT",
    description: "Alters the perceived mass of objects, amplifying or reducing weight. Lighter, heavier, your choice.",
  },
  {
    id: "singularity",
    name: "SINGULARITY",
    description: "Compresses mass into a controlled point of extreme density. A small point, a bigger tomorrow.",
  }
];

export default function CircularAbilitiesGallery() {
  const sectionRef = useRef<HTMLDivElement>(null);

  const { scrollYProgress } = useScroll({
    target: sectionRef,
    offset: ["start start", "end end"],
  });

  const smoothProgress = useSpring(scrollYProgress, {
    stiffness: 80,
    damping: 25,
    mass: 0.5,
  });

  // Rotate 360 degrees as user scrolls through the section
  const rotation = useTransform(smoothProgress, [0, 1], [0, -360]);
  
  // Cinematic tilt on X axis slightly for a better perspective
  const tiltX = useTransform(smoothProgress, [0, 1], [4, -4]);

  // Radius for the circular orbit
  const radius = 900; 

  return (
    <section 
      id="abilities"
      ref={sectionRef} 
      className="relative w-full h-[400vh] bg-[#050505] text-white font-sans selection:bg-white selection:text-black"
    >
      <div className="sticky top-0 w-full h-screen overflow-hidden flex items-center justify-center">
        
        {/* Background Ambient FX */}
        <div className="absolute inset-0 z-0 opacity-60 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-[#111118] via-[#050505] to-[#050505] pointer-events-none" />

        {/* Cinematic Header */}
        <div className="absolute top-[8%] md:top-[12%] left-[6%] md:left-[8%] z-50 pointer-events-none">
          <h2 
            className="text-5xl md:text-7xl lg:text-8xl font-bold tracking-[0.2em] uppercase"
            style={{
              fontFamily: "var(--font-display)",
              background: "linear-gradient(to bottom right, #ffffff, #888888)",
              WebkitBackgroundClip: "text",
              WebkitTextFillColor: "transparent",
              filter: "drop-shadow(0 4px 12px rgba(0,0,0,0.8))",
            }}
          >
            ABILITIES
          </h2>
          <div className="mt-4 flex flex-col gap-1 text-[10px] md:text-xs tracking-[0.3em] text-white/40 font-mono uppercase">
            <span>Gravity</span>
            <span>Obeys</span>
            <span>A Higher</span>
            <span>Debt</span>
          </div>
        </div>

        {/* 3D Scene Container */}
        <div 
          className="relative w-full h-full flex justify-center items-center pointer-events-none z-10"
          style={{ perspective: "1800px" }}
        >
          {/* Rotating Central Core */}
          <motion.div
            style={{
              rotateY: rotation,
              rotateX: tiltX,
              transformStyle: "preserve-3d",
            }}
            className="relative w-[300px] md:w-[340px] h-[450px] md:h-[520px] flex justify-center items-center will-change-transform"
          >
            {ABILITIES.map((ability, index) => {
              const angle = (360 / ABILITIES.length) * index;
              
              return (
                <div
                  key={ability.id}
                  className="absolute top-0 left-0 w-full h-full backface-hidden"
                  style={{
                    transform: `rotateY(${angle}deg) translateZ(${radius}px)`,
                    transformStyle: "preserve-3d",
                  }}
                >
                  {/* The Physical Card */}
                  <div className="relative w-full h-full bg-[#0a0a0a] border border-[#222] overflow-hidden group rounded-sm shadow-2xl">
                    {/* Placeholder Background */}
                    <div className="absolute inset-0 bg-gradient-to-b from-[#111] to-[#050505] flex flex-col items-center justify-center overflow-hidden">
                       <div className="w-[120%] h-[120%] absolute opacity-10 blur-3xl bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-white/20 to-transparent" />
                       <div className="w-[40px] h-[1px] bg-white/20 mb-4" />
                       <span className="text-white/10 font-mono text-xs tracking-widest uppercase">Visual Asset Pending</span>
                    </div>
                    
                    {/* Dark gradient overlay for text legibility */}
                    <div className="absolute inset-0 bg-gradient-to-t from-black via-black/60 to-transparent opacity-90" />
                    
                    {/* Card Content */}
                    <div className="absolute bottom-0 left-0 w-full p-8 md:p-10 transform translate-z-10 flex flex-col">
                      <div className="text-[#bf953f] text-xs font-mono tracking-[0.2em] mb-4 opacity-80">
                        0{index + 1}
                      </div>
                      <h3 
                        className="text-2xl md:text-3xl mb-4 tracking-[0.15em] text-white uppercase"
                        style={{ fontFamily: 'var(--font-display)' }}
                      >
                        {ability.name}
                      </h3>
                      <div className="w-8 h-[1px] bg-[#bf953f]/50 mb-6" />
                      <p 
                        className="text-xs md:text-sm text-white/50 leading-[1.8] tracking-wider uppercase font-sans"
                      >
                        {ability.description}
                      </p>
                    </div>
                    
                    {/* Hover Glow Edge Effect */}
                    <div className="absolute inset-0 border border-[#bf953f]/0 group-hover:border-[#bf953f]/30 transition-colors duration-700 pointer-events-auto cursor-default" />
                  </div>
                </div>
              );
            })}
          </motion.div>
        </div>
      </div>
    </section>
  );
}
