"use client";

import React, { useRef, useState, useCallback, useMemo, useEffect } from "react";
import { motion, useScroll, useTransform, useSpring } from "framer-motion";

// The character images provided by the user
const CHARACTER_IMAGES: string[] = [
  "/images/character/media_1789375360773.jpg",
  "/images/character/media_1789375381712.jpg",
  "/images/character/media_1789375381771.jpg",
  "/images/character/media_1789375381962.jpg",
  "/images/character/media_1789375382002.jpg",
  "/images/character/media_1789375360773.jpg",
  "/images/character/media_1789375381712.jpg",
  "/images/character/media_1789375381771.jpg",
  "/images/character/media_1789375381962.jpg",
  "/images/character/media_1789375382002.jpg",
  "/images/character/media_1789375360773.jpg",
  "/images/character/media_1789375381712.jpg",
  "/images/character/media_1789375381771.jpg",
  "/images/character/media_1789375381962.jpg",
];

interface ImageCardProps {
  src: string;
  onLoad?: () => void;
}

const ImageCard = ({ src, onLoad }: ImageCardProps) => {
  return (
    <div className="w-full h-[200px] sm:h-[300px] md:h-[400px] flex-shrink-0 bg-[#111] border border-[#222] transition-transform duration-300 hover:scale-[1.02] cursor-pointer relative will-change-transform backface-hidden preserve-3d flex items-center justify-center">
      {src ? (
        <img
          src={src}
          alt="ANCHOR Character"
          loading="lazy"
          onLoad={onLoad}
          className="w-full h-full object-cover opacity-80 hover:opacity-100 transition-opacity duration-300 rounded-sm"
        />
      ) : (
        <div className="text-[#333] text-sm uppercase tracking-widest font-bold">Image Needed</div>
      )}
    </div>
  );
};

export default function ParallaxGallery() {
  const containerRef = useRef<HTMLElement>(null);
  const [isReady, setIsReady] = useState(false);
  const loadedCountRef = useRef(0);

  const handleItemLoad = useCallback(() => {
    loadedCountRef.current += 1;
    if (!isReady && loadedCountRef.current >= 1) setIsReady(true);
  }, [isReady]);

  useEffect(() => {
    const t = setTimeout(() => setIsReady(true), 1200);
    return () => clearTimeout(t);
  }, []);

  const colMedia = useMemo(() => {
    const col1Base = CHARACTER_IMAGES.filter((_, i) => i % 4 === 0);
    const col2Base = CHARACTER_IMAGES.filter((_, i) => i % 4 === 1);
    const col3Base = CHARACTER_IMAGES.filter((_, i) => i % 4 === 2);
    const col4Base = CHARACTER_IMAGES.filter((_, i) => i % 4 === 3);

    return {
      col1: [...col1Base, ...col1Base, ...col1Base],
      col2: [...col2Base, ...col2Base, ...col2Base],
      col3: [...col3Base, ...col3Base, ...col3Base],
      col4: [...col4Base, ...col4Base, ...col4Base],
    };
  }, []);

  // LINKED SCROLL: Uses normal page scroll relative to this section
  const { scrollYProgress } = useScroll({
    target: containerRef,
    offset: ["start start", "end end"],
  });

  const smoothProgress = useSpring(scrollYProgress, {
    stiffness: 80,
    damping: 25,
    mass: 0.5,
  });

  // Banner animations (unfurling the background)
  const bannerHeight = useTransform(smoothProgress, [0, 0.2], ["90vh", "100vh"]);
  const bannerRadius = useTransform(smoothProgress, [0, 0.2], ["24px", "0px"]);
  const bannerBorderWidth = useTransform(smoothProgress, [0, 0.2], ["2px", "0px"]);

  // 3D Matrix animations (eases toward 0 around 60%, stays flat until 100%)
  const rotateY = useTransform(smoothProgress, [0, 0.6, 1], [-15, 0, 0]);
  const rotateX = useTransform(smoothProgress, [0, 0.6, 1], [8, 0, 0]);
  const rotateZ = useTransform(smoothProgress, [0, 0.6, 1], [3, 0, 0]);
  const translateZ = useTransform(smoothProgress, [0, 0.6, 1], [-120, 0, 0]);
  const scale = useTransform(smoothProgress, [0, 0.6, 1], [0.88, 1, 1]);

  // Track columns parallax animations (Staggered layered depth)
  const yCol1 = useTransform(smoothProgress, [0, 1], ["0vh", "-100vh"]);
  const yCol2 = useTransform(smoothProgress, [0, 1], ["20vh", "-120vh"]);
  const yCol3 = useTransform(smoothProgress, [0, 1], ["-10vh", "-140vh"]);
  const yCol4 = useTransform(smoothProgress, [0, 1], ["10vh", "-90vh"]);

  return (
    <div 
      className="w-full bg-[#050505]"
    >
      <section
        ref={containerRef}
        className="relative w-full h-[500vh] bg-[#050505] text-white font-sans selection:bg-white selection:text-black"
      >
        <div className="sticky top-0 h-screen w-full flex justify-center items-center overflow-hidden">
          
          <div className="absolute top-[10%] left-[8%] z-50 pointer-events-none">
            <h2 
              className="text-5xl md:text-7xl font-bold tracking-[0.2em] uppercase"
              style={{
                fontFamily: "var(--font-display)",
                background: "linear-gradient(to right, #bf953f, #fcf6ba, #b38728, #fbf5b7, #aa771c)",
                backgroundSize: "200% auto",
                WebkitBackgroundClip: "text",
                WebkitTextFillColor: "transparent",
                filter: "drop-shadow(0 10px 20px rgba(0,0,0,0.9))",
              }}
            >
              CHARACTER
            </h2>
          </div>

          <motion.div
            style={{
              width: "100vw",
              height: "100vh",
            }}
            className="relative bg-[#050505] overflow-hidden flex items-center justify-center max-w-[1920px] mx-auto will-change-transform backface-hidden preserve-3d"
          >
            <div
              className="absolute inset-0 flex justify-center items-center pointer-events-none"
              style={{ perspective: "1200px" }}
            >
              {/* Ambient Shadow Box Masking */}
              <div className="absolute inset-0 z-20 shadow-[inset_0_100px_150px_-50px_rgba(5,5,5,1),inset_0_-100px_150px_-50px_rgba(5,5,5,1)]" />
              <div className="absolute inset-0 z-20 shadow-[inset_150px_0_150px_-50px_rgba(5,5,5,1),inset_-150px_0_150px_-50px_rgba(5,5,5,1)]" />

              {/* Parallax Image Grid Matrix */}
              <motion.div
                style={{
                  rotateX,
                  rotateY,
                  rotateZ,
                  z: translateZ,
                  scale,
                  transformStyle: "preserve-3d",
                }}
                className="flex gap-6 md:gap-8 justify-center items-center w-[90vw] md:w-[85vw] h-[85vh] origin-center opacity-100 will-change-transform backface-hidden"
              >
                <motion.div style={{ y: yCol1 }} className="flex flex-col gap-6 md:gap-8 w-[40vw] md:w-[22vw] min-w-[150px] pointer-events-auto">
                  {colMedia.col1.map((src, index) => (
                    <ImageCard key={`col1-${index}`} src={src} onLoad={handleItemLoad} />
                  ))}
                </motion.div>

                <motion.div style={{ y: yCol2 }} className="flex flex-col gap-6 md:gap-8 w-[40vw] md:w-[22vw] min-w-[150px] pointer-events-auto">
                  {colMedia.col2.map((src, index) => (
                    <ImageCard key={`col2-${index}`} src={src} onLoad={handleItemLoad} />
                  ))}
                </motion.div>

                <motion.div style={{ y: yCol3 }} className="hidden md:flex flex-col gap-6 md:gap-8 w-[22vw] min-w-[150px] pointer-events-auto">
                  {colMedia.col3.map((src, index) => (
                    <ImageCard key={`col3-${index}`} src={src} onLoad={handleItemLoad} />
                  ))}
                </motion.div>

                <motion.div style={{ y: yCol4 }} className="hidden md:flex flex-col gap-6 md:gap-8 w-[22vw] min-w-[150px] pointer-events-auto">
                  {colMedia.col4.map((src, index) => (
                    <ImageCard key={`col4-${index}`} src={src} onLoad={handleItemLoad} />
                  ))}
                </motion.div>
              </motion.div>
            </div>
          </motion.div>
        </div>
      </section>
    </div>
  );
}
